def bellman_ford(graph, source, num_vertices):
    # Initialize distances with infinity for all nodes except the source
    distances = {node: float('inf') for node in range(num_vertices)}
    distances[source] = 0

    # Relax edges num_vertices - 1 times
    for _ in range(num_vertices - 1):
        updated = False
        for u, v, w in graph:
            if distances[u] != float('inf') and distances[v] > distances[u] + w:
                distances[v] = distances[u] + w
                updated = True
        if not updated:
            break  # No more updates, can exit early

    # Check for negative weight cycles
    for u, v, w in graph:
        if distances[u] != float('inf') and distances[v] > distances[u] + w:
            return "Negative weight cycle detected"

    return distances

