from collections import Counter

def most_frequent_and_kth_character(s: str, k: int) -> (str, str):
    if not s:
        return ('', 'None')

    counts = Counter(s)
    max_count = max(counts.values())
    candidates = [char for char, cnt in counts.items() if cnt == max_count]
    most_frequent = max(candidates)

    unique_chars = sorted(counts.keys())
    if k > len(unique_chars):
        kth_char = 'None'
    else:
        kth_char = unique_chars[k-1]

    return (most_frequent, kth_char)

