def replace_question_marks(s: str) -> str:
    result = []
    for c in s:
        if c == '?':
            if result:
                last = result[-1]
                for i in range(26):
                    candidate = chr(ord('a') + i)
                    if candidate != last:
                        result.append(candidate)
                        break
            else:
                result.append('a')
        else:
            result.append(c)
    return ''.join(result)

