def sum_divisible_by_3_or_5(n: int) -> int:
    def sum_divisible_by(k, m):
        if m <= 0:
            return 0
        p = m // k
        return k * p * (p + 1) // 2

    sum3 = sum_divisible_by(3, n)
    sum5 = sum_divisible_by(5, n)
    sum15 = sum_divisible_by(15, n)

    return sum3 + sum5 - sum15

