def minimum_number_of_trucks(n, m, package_weights, truck_capacities):
    # Check if any package weight exceeds all truck capacities
    max_package = max(package_weights)
    max_truck = max(truck_capacities)
    if max_package > max_truck:
        return -1

    # Sort packages in descending order and trucks in descending order
    packages = sorted(package_weights, reverse=True)
    trucks = sorted(truck_capacities, reverse=True)

    # Initialize the current load for each truck
    current_load = [0] * m

    for weight in packages:
        placed = False
        for i in range(m):
            if current_load[i] + weight <= trucks[i]:
                current_load[i] += weight
                placed = True
                break
        if not placed:
            return -1

    # Count the number of trucks with non-zero load
    count = 0
    for load in current_load:
        if load > 0:
            count += 1
    return count

