def evaluate_expression(expression: str) -> int:
    tokens = []
    current_number = ''
    for char in expression:
        if char.isdigit():
            current_number += char
        else:
            if current_number:
                tokens.append(int(current_number))
                current_number = ''
            if char in '+-*/':
                tokens.append(char)
    if current_number:
        tokens.append(int(current_number))

    precedence = {'+': 1, '-': 1, '*': 2, '/': 2}
    output = []
    op_stack = []

    for token in tokens:
        if isinstance(token, int):
            output.append(token)
        else:
            while op_stack and op_stack[-1] in precedence and precedence[op_stack[-1]] >= precedence[token]:
                output.append(op_stack.pop())
            op_stack.append(token)

    while op_stack:
        output.append(op_stack.pop())

    result = 0
    for token in output:
        if isinstance(token, int):
            result = result + token
        else:
            if token == '+':
                result += output.pop()
            elif token == '-':
                result -= output.pop()
            elif token == '*':
                result *= output.pop()
            elif token == '/':
                result = result // output.pop()

    return result

