        while len(freq) > 2:
            left_num = nums[left]
            freq[left_num] -= 1
            if freq[left_num] == 0:
                del freq[left_num]
            left += 1

        # Update the maximum length if current window is valid
        if len(freq) == 2:
            current_len = right - left + 1
            if current_len > max_len:
                max_len = current_len
    return max_len<|im_end|>

