def find_minimum_spanning_tree(n, m, edges):
    if n == 1:
        return 0
    if m == 0:
        return -1

    edges.sort(key=lambda x: x[2])
    parent = list(range(n + 1))
    rank = [1] * (n + 1)
    total = 0
    count = 0

    def find(u):
        if parent[u] != u:
            parent[u] = find(parent[u])
        return parent[u]

    for u, v, w in edges:
        root_u = find(u)
        root_v = find(v)
        if root_u != root_v:
            total += w
            count += 1
            if count == n - 1:
                break
            # Union by rank
            if rank[root_u] > rank[root_v]:
                parent[root_v] = root_u
            else:
                parent[root_u] = root_v
                if rank[root_u] == rank[root_v]:
                    rank[root_v] += 1

    return total if count == n - 1 else -1

