from typing import List

def rearrange_string(s: str) -> str:
    if not s:
        return ""
    counts = Counter(s)
    max_freq = max(counts.values())
    n = len(s)

    if max_freq > (n + 1) // 2:
        return ""

    sorted_chars = sorted(counts.items(), key=lambda x: (-x[1], x[0]))
    result = []
    last_char = None

    for char, count in sorted_chars:
        for _ in range(count):
            if last_char == char:
                return ""
            result.append(char)
            last_char = char

    return ''.join(result)

