from typing import List, Tuple

def min_crops(N: int, edges: List[Tuple[int, int]]) -> int:
    if N == 0:
        return 0
    # Build adjacency list
    adj = [[] for _ in range(N + 1)]
    for a, b in edges:
        adj[a].append(b)
        adj[b].append(a)

    color = [-1] * (N + 1)
    for i in range(1, N + 1):
        if color[i] == -1:
            queue = deque()
            queue.append(i)
            color[i] = 0
            while queue:
                u = queue.popleft()
                for v in adj[u]:
                    if color[v] == -1:
                        color[v] = 1 - color[u]
                        queue.append(v)

    max_color = 0
    for i in range(1, N + 1):
        if color[i] > max_color:
            max_color = color[i]
    return max_color + 1

