from typing import List, Tuple

def longest_nonconsecutive_subsequence(t: int, test_cases: List[Tuple[int, List[int]]]) -> List[int]:
    results = []
    for case in test_cases:
        n, arr = case
        if not arr:
            results.append(0)
            continue
        prev = arr[0]
        count = 1
        max_count = 1
        for i in range(1, n):
            current = arr[i]
            if current != prev:
                count += 1
                if count > max_count:
                    max_count = count
                prev = current
            else:
                count = 1
        results.append(max_count)
    return results

