@torch.compile(mode="reduce-overhead")
def customized_operations(input_tensor: torch.Tensor) -> torch.Tensor:
    """ Apply multiple CUDA Graph captures with memory management and conditional operations on the input tensor.

    Args:
    input_tensor (torch.Tensor): A 1D tensor of size n and dtype torch.float32 located on a CUDA device.

    Returns:
    torch.Tensor: A new tensor resulting from multiple graph operations applied efficiently.
    """
    sum_input = input_tensor.sum()
    if sum_input > 100:
        return (input_tensor + 5) + (input_tensor * 2)
    else:
        return (input_tensor + 5) - (input_tensor * 2)

