def evaluate_postfix(postfix):
    stack = []
    for token in postfix:
        if token in '+-*/()':
            if token == '(':
                stack.append(token)
            elif token == ')':
                if not stack:
                    raise ValueError("Mismatched parentheses")
                op = stack.pop()
                if op != '(':
                    raise ValueError("Mismatched parentheses")
            else:
                if len(stack) < 2:
                    raise ValueError("Invalid expression")
                b = stack.pop()
                a = stack.pop()
                if token == '+':
                    res = a + b
                elif token == '-':
                    res = a - b
                elif token == '*':
                    res = a * b
                elif token == '/':
                    res = a / b
                else:
                    raise ValueError("Invalid operator")
                stack.append(res)
        elif token.isdigit():
            stack.append(int(token))
        else:
            raise ValueError("Invalid token")
    if len(stack) != 1:
        raise ValueError("Invalid expression")
    return stack.pop()

# Example usage:
postfix_expression = "3 4 + 2 *"
print(evaluate_postfix(postfix_expression))  # Output: 14

