from typing import List

def product_except_self(nums: List[int]) -> List[int]:
    n = len(nums)
    if n == 1:
        return [1]

    left = [1] * n
    for i in range(1, n):
        left[i] = left[i-1] * nums[i-1]

    right = [1] * n
    for i in range(n-2, -1, -1):
        right[i] = right[i+1] * nums[i+1]

    result = [left[i] * right[i] for i in range(n)]
    return result

