def add_sparse_matrices(mat1, mat2):
    # Collect all unique rows from both matrices
    all_rows = set(mat1.keys()).union(set(mat2.keys()))
    result = {}

    for row in all_rows:
        # Initialize the row's columns dictionary
        row_dict = {}

        # Add elements from mat1
        if row in mat1:
            for col, val in mat1[row].items():
                row_dict[col] = val

        # Add elements from mat2
        if row in mat2:
            for col, val in mat2[row].items():
                if col in row_dict:
                    row_dict[col] += val
                else:
                    row_dict[col] = val

        # Only include the row if it has non-zero elements
        if row_dict:
            result[row] = row_dict

    return result

