def snakepath_grid(n):
    grid = [[0 for _ in range(n)] for _ in range(n)]
    for i in range(n):
        if i % 2 == 0:
            for j in range(n):
                grid[i][j] = i * n + j + 1
        else:
            for j in range(n-1, -1, -1):
                grid[i][j] = i * n + (n - j)
    return grid

