import string

STOP_WORDS = ['and', 'the', 'in', 'of', 'to', 'it', 'is', 'a', 'for']

def analyze_word_frequency(text: str) -> dict[str, int]:
    """
    Analyze word frequency from the given text string.

    Args:
    text (str): A string containing the text to analyze.

    Returns:
    dict[str, int]: Dictionary of word frequencies.
    """
    word_freq = {}
    words = text.split()
    for word in words:
        # Convert to lower case
        word = word.lower()
        # Remove punctuation from beginning and end
        word = word.strip(string.punctuation)
        # Skip stop words
        if word in STOP_WORDS:
            continue
        if word in word_freq:
            word_freq[word] += 1
        else:
            word_freq[word] = 1
    return word_freq

# Test cases to validate the solution
if __name__ == "__main__":
    print(analyze_word_frequency("Hello, world! This is a test. Hello world!"))  # Output: {"hello": 2, "world": 2, "this": 1, "test": 1}
    print(analyze_word_frequency("Python is great. Python, python, Python!"))    # Output: {"python": 4, "great": 1}

