from typing import List, Tuple

def exist(board: List[List[str]], word: str) -> bool:
    if not board or not board[0]:
        return False
    rows = len(board)
    cols = len(board[0])
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    def dfs(i, j, index, visited):
        if index == len(word) - 1:
            return True
        for dx, dy in directions:
            ni, nj = i + dx, j + dy
            if 0 <= ni < rows and 0 <= nj < cols:
                if not visited[ni][nj] and board[ni][nj] == word[index + 1]:
                    visited[ni][nj] = True
                    if dfs(ni, nj, index + 1, visited):
                        return True
                    visited[ni][nj] = False
        return False

    for i in range(rows):
        for j in range(cols):
