import os

def most_recently_modified(directory):
    if not os.path.isdir(directory):
        return None, None

    files = os.listdir(directory)
    candidates = []

    for filename in files:
        file_path = os.path.join(directory, filename)
        if os.path.isfile(file_path):
            try:
                mtime = os.path.getmtime(file_path)
                candidates.append((file_path, mtime))
            except OSError:
                continue  # Skip files that can't be accessed

    if not candidates:
        return None, None

    max_mtime = max(mtime for file_path, mtime in candidates)
    max_file = next((file for file, mtime in candidates if mtime == max_mtime), None)

    return max_file, max_mtime

