from collections import deque
from typing import List, Tuple

def determine_capital(N: int, M: int, A: int, B: int, residents: List[int], roads: List[Tuple[int, int]]) -> int:
    # Build adjacency list
    adj = [[] for _ in range(N + 1)]
    for u, v in roads:
        adj[u].append(v)
        adj[v].append(u)

    def bfs(start):
        distances = [-1] * (N + 1)
        queue = deque()
        queue.append(start)
        distances[start] = 0
        while queue:
            u = queue.popleft()
            for v in adj[u]:
                if distances[v] == -1:
                    distances[v] = distances[u] + 1
                    queue.append(v)
        return distances

    # Compute distances for city A
    dist_A = bfs(A)
    max_dist_A = 0
    for i in range(1, N + 1):
        if residents[i] > 0:
            if dist_A[i] > max_dist_A:
                max_dist_A = dist_A[i]

    # Compute distances for city B
    dist_B = bfs(B)
    max_dist_B = 0
    for i in range(1, N + 1):
        if residents[i] > 0:
            if dist_B[i] > max_dist_B:
                max_dist_B = dist_B[i]

    # Determine the result
    if max_dist_A < max_dist_B:
        return A
    elif max_dist_B < max_dist_A:
        return B
    else:
        return min(A, B)

