from collections import deque
from typing import List, Tuple

def shortest_path(n: int, grid: List[List[int]], start: Tuple[int, int], destination: Tuple[int, int]) -> int:
    if start == destination:
        return 0

    start_r, start_c = start
    dest_r, dest_c = destination

    if grid[start_r][start_c] != 0 or grid[dest_r][dest_c] != 0:
        return -1

    visited = [[False for _ in range(n)] for _ in range(n)]
    queue = deque()
    queue.append((start_r, start_c, 0))
    visited[start_r][start_c] = True

    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    while queue:
        r, c, dist = queue.popleft()

        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if 0 <= nr < n and 0 <= nc < n:
                if not visited[nr][nc] and grid[nr][nc] == 0:
                    if (nr, nc) == (dest_r, dest_c):
                        return dist + 1
                    visited[nr][nc] = True
                    queue.append((nr, nc, dist + 1))

    return -1

