def validate_isbn_10(isbn: str) -> bool:
    if len(isbn) != 10:
        return False
    if not isbn.isalnum():
        return False
    total = 0
    for i in range(10):
        char = isbn[i]
        if char.isdigit():
            digit = int(char)
        else:
            if char == 'X':
                digit = 10
            else:
                return False
        total += digit * (10 - i)
    return total % 11 == 0

