def max_style_points(budget: int, items: list) -> int:
    if not items:
        return 0
    items.sort(key=lambda x: x[1] / x[0], reverse=True)
    dp = [0] * (budget + 1)
    for cost, points in items:
        for j in range(budget, cost - 1, -1):
            if dp[j - cost] + points > dp[j]:
                dp[j] = dp[j - cost] + points
    return dp[budget]

