from typing import List

def eatenApples(arr: List[int], days: List[int]) -> int:
    heap = []
    total = 0
    i = 0
    while i < len(arr) or heap:
        if not heap:
            if i >= len(arr):
                break
            a = arr[i]
            d = days[i]
            if a == 0:
                i += 1
                continue
            heapq.heappush(heap, (d, a))
            i += 1
        else:
            d, a = heapq.heappop(heap)
            if a == 0:
                continue
            if d == 0:
                continue
            if a <= 1:
                total += 1
                a = 0
            else:
                total += 1
                a -= 1
            if a > 0:
                heapq.heappush(heap, (d - 1, a))
    return total

