from typing import List

def spell_check(word: str, dictionary: List[str]) -> str:
    if not dictionary:
        return ""

    def edit_distance(s1: str, s2: str) -> int:
        m = len(s1)
        n = len(s2)
        dp = [[0] * (n + 1) for _ in range(m + 1)]

        for i in range(m + 1):
            dp[i][0] = i
        for j in range(n + 1):
            dp[0][j] = j

        for i in range(1, m + 1):
            for j in range(1, n + 1):
                if s1[i-1] == s2[j-1]:
                    dp[i][j] = dp[i-1][j-1]
                else:
                    dp[i][j] = 1 + min(dp[i-1][j], dp[i][j-1], dp[i-1][j-1])

        return dp[m][n]

    min_distance = float('inf')
    best_word = ""

    for d in dictionary:
        current_distance = edit_distance(word, d)
        if current_distance < min_distance:
            min_distance = current_distance
            best_word = d

    return best_word

