def evaluate_expression(input):
    tokens = []
    current_number = ''
    for c in input:
        if c.isdigit():
            current_number += c
        else:
            if current_number:
                tokens.append(int(current_number))
                current_number = ''
            if c in '+-*/':
                tokens.append(c)
    if current_number:
        tokens.append(int(current_number))

    stack = []
    operators = []

    for token in tokens:
        if isinstance(token, int):
            stack.append(token)
        else:
            while operators and operators[-1] in '+-' and precedence(token) <= precedence(operators[-1]):
                op = operators.pop()
                a = stack.pop()
                b = stack.pop()
                res = b op a
                stack.append(res)
            operators.append(token)

    while operators:
        op = operators.pop()
        a = stack.pop()
        b = stack.pop()
        res = b op a
        stack.append(res)

    return int(stack[0])

def precedence(op):
    if op in '+-':
        return 1
    elif op in '*/':
        return 2
    else:
        return 0

