def linear_interpolation(points, num_points, x_start, x_end):
    if not points:
        return []

    x_values = []
    for i in range(num_points):
        x = x_start + i * (x_end - x_start) / (num_points - 1)
        x_values.append(x)

    y_values = []
    for x in x_values:
        min_x = min(p[0] for p in points)
        max_x = max(p[0] for p in points)
        if x < min_x:
            y = points[0][1]
        elif x > max_x:
            y = points[-1][1]
        else:
            # Find the two points that bracket x
            prev_x = None
            prev_y = None
            for p in points:
                if p[0] > x:
                    break
                if prev_x is None:
                    prev_x = p[0]
                    prev_y = p[1]
                else:
                    if p[0] > x:
                        # Calculate y using linear interpolation
                        slope = (p[1] - prev_y) / (p[0] - prev_x)
                        y = prev_y + slope * (x - prev_x)
                        y_values.append(y)
                        break
            else:
                # x is exactly at the last point
                y = prev_y
                y_values.append(y)
        y_values.append(y)

    return y_values

