def has_cycle(edges):
    if not edges:
        return False
    n = max(u for u, v in edges) + 1
    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
    visited = [False] * n
    recursion_stack = [False] * n

    def dfs(node):
        visited[node] = True
        recursion_stack[node] = True
        for neighbor in adj[node]:
            if not visited[neighbor]:
                if dfs(neighbor):
                    return True
            elif recursion_stack[neighbor]:
                return True
        recursion_stack[node] = False
        return False

    for node in range(n):
        if not visited[node]:
            if dfs(node):
                return True
    return False

