def findRepeatedPhrases(text, phraseLength):
    words = text.split()
    n = len(words)
    if n < phraseLength:
        return []

    first_occurrence = {}
    counts = {}

    for i in range(n - phraseLength + 1):
        phrase = ' '.join(words[i:i+phraseLength])
        if phrase in first_occurrence:
            counts[phrase] += 1
        else:
            first_occurrence[phrase] = i
            counts[phrase] = 1

    repeated_phrases = [phrase for phrase in counts if counts[phrase] > 1]
    repeated_phrases.sort(key=lambda x: first_occurrence[x])

    return repeated_phrases

