def detect_ddos(log_entries: list, threshold: int) -> list:
    ip_timestamps = {}
    for entry in log_entries:
        ip = entry['ip_address']
        ts = entry['timestamp']
        if ip not in ip_timestamps:
            ip_timestamps[ip] = []
        ip_timestamps[ip].append(ts)

    result = set()
    for ip, timestamps in ip_timestamps.items():
        timestamps.sort()
        n = len(timestamps)
        for i in range(n):
            window_start = timestamps[i]
            window_end = window_start + 10
            count = 0
            for j in range(i, n):
                if timestamps[j] < window_end:
                    count += 1
                else:
                    break
            if count > threshold:
                result.add(ip)
                break  # No need to check further for this IP
    return list(result)

