def fraction_to_decimal(fraction_str: str) -> float:
    parts = fraction_str.split()
    if len(parts) == 1:
        # It's a single part, either a whole number or a fraction
        if '/' in parts[0]:
            numerator, denominator = map(int, parts[0].split('/'))
            return numerator / denominator
        else:
            return float(parts[0])
    else:
        # It's a mixed number
        whole = int(parts[0])
        fraction_part = parts[1]
        if '/' in fraction_part:
            num, den = map(int, fraction_part.split('/'))
            return whole + num / den
        else:
            return whole + float(fraction_part)

