class IntervalCollection:
    def __init__(self):
        self.intervals = []

    def add(self, interval: Tuple[int, int]):
        a, b = interval
        self.intervals.append((a, b))

    def remove(self, interval: Tuple[int, int]):
        a, b = interval
        self.intervals = [i for i in self.intervals if not (i[0] == a and i[1] == b)]

    def query(self, point: int) -> bool:
        for a, b in self.intervals:
            if a <= point <= b:
                return True
        return False

    def merge(self) -> List[Tuple[int, int]]:
        if not self.intervals:
            return []
        sorted_intervals = sorted(self.intervals, key=lambda x: x[0])
        merged = []
        current_start, current_end = sorted_intervals[0]
        for a, b in sorted_intervals[1:]:
            if a <= current_end:
                current_end = max(current_end, b)
            else:
                merged.append((current_start, current_end))
                current_start, current_end = a, b
        merged.append((current_start, current_end))
        return merged

