from xml.dom.minidom import parseString, Node
from xml.parsers.expat import ExpatError

class XMLTransformationError(Exception):
    def __init__(self, message):
        self.message = message
        super().__init__(self.message)

def transform_xml_document(xml_string: str) -> str:
    try:
        doc = parseString(xml_string)
    except ExpatError as e:
        raise XMLTransformationError(f"XML parsing error: {e}")

    # Add the modified attribute to the root element
    root = doc.documentElement
    root.setAttribute('modified', 'true')

    # Process each item element
    for item in doc.getElementsByTagName('item'):
        item_type = item.getAttribute('type')
        quantity_elem = item.getElementsByTagName('quantity')[0]
        quantity_str = quantity_elem.firstChild.nodeValue
        try:
            quantity = int(quantity_str)
        except ValueError:
            raise XMLTransformationError(f"Non-integer value in 'quantity' element")
        new_quantity = quantity * 2
        quantity_elem.firstChild.nodeValue = str(new_quantity)
        new_tag = f"{item_type}Item"
        item.replaceWholeChild(item, doc.createElement(new_tag))

    return doc.toxml()

