from collections import deque
from typing import List, Tuple

def make_kingdom_tree(n: int, m: int, edges: List[Tuple[int, int]]) -> str:
    if n == 1:
        return "YES"

    # Build adjacency list
    adj = [[] for _ in range(n + 1)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    # Check if the graph is connected using BFS
    visited = [False] * (n + 1)
    queue = deque()
    queue.append(1)
    visited[1] = True
    count = 1

    while queue:
        u = queue.popleft()
        for v in adj[u]:
            if not visited[v]:
                visited[v] = True
                count += 1
                queue.append(v)

    if count != n:
        return "NO"

    # Check for cycles using DFS
    parent = [-1] * (n + 1)
    visited = [False] * (n + 1)
    for i in range(1, n + 1):
        if not visited[i]:
            stack = [(i, -1, False)]
            while stack:
                u, p, processed = stack.pop()
                if processed:
                    continue
                visited[u] = True
                for v in adj[u]:
                    if v == p:
                        continue
                    if visited[v]:
                        if parent[v] == p:
                            continue
                        else:
                            return "NO"
                    parent[v] = u
                    stack.append((v, u, True))
                    stack.append((u, p, False))

    # Find the edges to remove
    edges_to_remove = []
    for i in range(m):
        u, v = edges[i]
        if parent[v] == u or parent[u] == v:
            edges_to_remove.append(i + 1)

    edges_to_remove.sort()
    return f"YES\n{' '.join(map(str, edges_to_remove))}"

