from typing import List

def common_activities(n: int, activities_list: List[str]) -> str:
    if n == 0:
        return "No common activities"

    all_activities = set()
    for player in activities_list:
        activities = player.split()
        all_activities.update(activities)

    if not all_activities:
        return "No common activities"

    common = all_activities
    for player in activities_list:
        player_activities = set(player.split())
        common = common.intersection(player_activities)

    if not common:
        return "No common activities"

    sorted_common = sorted(common)
    return ' '.join(sorted_common)

