def reverse_k_words(sentence: str, k: int) -> str:
    words = sentence.split()
    if k <= 0:
        return sentence
    if k >= len(words):
        words = words[::-1]
    else:
        words[:k] = words[:k][::-1]
    return ' '.join(words)

