from collections import deque

def max_problems_solved(T, cases):
    results = []
    for case in cases:
        P, D, deps = case
        # Build adjacency list and in-degree array
        adj = [[] for _ in range(P + 1)]
        in_degree = [0] * (P + 1)
        for x, y in deps:
            adj[x].append(y)
            in_degree[y] += 1

        # Kahn's algorithm to check for cycles and compute topological order
        queue = deque()
        for i in range(1, P + 1):
            if in_degree[i] == 0:
                queue.append(i)

        count = 0
        while queue:
            u = queue.popleft()
            count += 1
            for v in adj[u]:
                in_degree[v] -= 1
                if in_degree[v] == 0:
                    queue.append(v)

        if count != P:
            results.append(-1)
        else:
            results.append(P)

    return results

