from collections import defaultdict

def solve(T, cases):
    results = []
    for case in cases:
        n, m, grid = case
        # Check if all rows have the same set of elements
        row_sets = [set(row) for row in grid]
        if not all(s == row_sets[0] for s in row_sets):
            results.append(-1)
            continue

        # Check if all columns have the same set of elements
        col_sets = [set(grid[i][j] for i in range(n)) for j in range(m)]
        if not all(s == col_sets[0] for s in col_sets):
            results.append(-1)
            continue

        # Check if all elements are the same
        all_same = True
        for row in grid:
            for num in row:
                if num != grid[0][0]:
                    all_same = False
                    break
            if not all_same:
                break
        if not all_same:
            results.append(-1)
            continue

        # Calculate the number of swaps
        count = defaultdict(int)
        for row in grid:
            for num in row:
                count[num] += 1
        total = 0
        for num in count:
            if count[num] % m != 0:
                results.append(-1)
                break
            total += count[num] // m
        results.append(total)

    return results

