def process_bytearrays(string_length_pairs: List[Tuple[str, int]], final_length: int) -> str:
    if final_length == 0:
        return ''
    total = sum(l for s, l in string_length_pairs)
    if total >= final_length:
        result = ''.join(s for s, l in string_length_pairs)
        return result[:final_length]
    else:
        result = ''.join(s for s, l in string_length_pairs)
        padding = final_length - total
        return result + '\x00' * padding

