def count_shortest_paths(grid) -> int:
    if not grid or not grid[0]:
        return 0
    m = len(grid)
    n = len(grid[0])
    if grid[0][0] == 1 or grid[m-1][n-1] == 1:
        return 0
    dp = [[0 for _ in range(n)] for _ in range(m)]
    dp[0][0] = 1
    for i in range(m):
        for j in range(n):
            if i == 0 and j == 0:
                continue
            if grid[i][j] == 1:
                dp[i][j] = 0
                continue
            top = dp[i-1][j] if i > 0 else 0
            left = dp[i][j-1] if j > 0 else 0
            dp[i][j] = top + left
    return dp[m-1][n-1]

