def multiply_sparse_matrices(A, B):
    # Convert A to a dictionary of lists for efficient access
    A_dict = {}
    for i in range(len(A)):
        row = A[i]
        for j in range(len(row)):
            if row[j] != 0:
                if i not in A_dict:
                    A_dict[i] = []
                A_dict[i].append((j, row[j]))

    # Convert B to a dictionary of lists for efficient access
    B_dict = {}
    for i in range(len(B)):
        row = B[i]
        for j in range(len(row)):
            if row[j] != 0:
                if i not in B_dict:
                    B_dict[i] = []
                B_dict[i].append((j, row[j]))

    # Initialize result matrix with zeros
    m = len(A)
    l = len(B[0]) if B else 0
    result = [[0 for _ in range(l)] for _ in range(m)]

    # Compute each element of the result matrix
    for i in range(m):
        if i not in A_dict:
            continue
        for j in range(l):
            if j not in B_dict:
                continue
            # Get the list of non-zero elements for row i in A
            a_list = A_dict[i]
            # Get the list of non-zero elements for column j in B
            b_list = B_dict[j]
            # Compute the dot product of a_list and b_list
            sum_val = 0
            for a_j, a_val in a_list:
                for b_j, b_val in b_list:
                    if a_j == b_j:
                        sum_val += a_val * b_val
            result[i][j] = sum_val

    return result

