            b_list = B_dict[j]
            # Compute the dot product of a_list and b_list
            sum_val = 0
            for a_j, a_val in a_list:
                for b_j, b_val in b_list:
                    if a_j == b_j:
                        sum_val += a_val * b_val
            result[i][j] = sum_val

