class RandomListNode:
    def __init__(self, label: int = 0, next: 'RandomListNode' = None, random: 'RandomListNode' = None):
        self.label = label
        self.next = next
        self.random = random

def copy_random_pointer(head: RandomListNode) -> RandomListNode:
    if not head:
        return None

    # First pass: create a mapping from each node to its copy
    node_map = {}
    current = head
    while current:
        new_node = RandomListNode(current.label)
        node_map[current] = new_node
        current = current.next

    # Second pass: assign next and random pointers
    current = head
    while current:
        new_node = node_map[current]
        new_node.next = node_map.get(current.next)
        new_node.random = node_map.get(current.random)
        current = current.next

    return node_map[head]

