def schedule_conference(input_str: str) -> list:
    lines = [line.strip() for line in input_str.split('\n') if line.strip()]
    if not lines:
        return []
    n = int(lines[0])
    sessions = []
    for i in range(1, n + 1):
        parts = lines[i].split()
        if len(parts) >= 2:
            a = int(parts[0])
            b = int(parts[1])
            sessions.append((a, b))
    sessions.sort()
    count = 0
    last_end = -1
    for a, b in sessions:
        if a > last_end:
            count += 1
            last_end = b
    return [count]

