        self.nal_units.append(nal_unit)

        # Check if the NAL unit has any dependencies
        if nal_unit.dependency_type is not None:
            # Get the dependencies of the NAL unit
            dependencies = []
            if nal_unit.dependency_type == 'temporal':
                # For temporal dependencies, find all NAL units with a lower temporal layer
                for nu in self.nal_units:
                    if nu.temporal_layer < nal_unit.temporal_layer and nu not in dependencies:
                        dependencies.append(nu)
            elif nal_unit.dependency_type == 'spatial':
                # For spatial dependencies, find all NAL units with the same temporal layer
