                for nu in self.nal_units:
                    if nu.temporal_layer == nal_unit.temporal_layer and nu.packet_type < nal_unit.packet_type and nu not in dependencies:
                        dependencies.append(nu)

            # Add the dependencies to the NAL unit
            nal_unit.dependencies = dependencies

            # Check if all dependencies are in the buffer
            for dependency in dependencies:
                if dependency not in self.nal_units:
                    # If a dependency is not in the buffer, return False
                    return False

        # If the NAL unit has no dependencies or all dependencies are in the buffer, return True
        return True

