def min_skill_diff(n: int, skill_levels: List[int]) -> int:
    total = sum(skill_levels)
    target = total // 2
    dp = [False] * (target + 1)
    dp[0] = True  # Base case: sum of 0 is always possible

    for num in skill_levels:
        for j in range(target, num - 1, -1):
            if dp[j - num]:
                dp[j] = True

    # Find the maximum achievable sum that is <= target
    max_sum = 0
    for j in range(target, -1, -1):
        if dp[j]:
            max_sum = j
            break

    return total - 2 * max_sum

