def organize_indexes(indexes: str) -> str:
    if not indexes:
        return ""
    numbers = list(map(int, indexes.split(',')))
    if len(numbers) == 1:
        return str(numbers[0])
    ranges = []
    current_start = numbers[0]
    current_end = numbers[0]
    for num in numbers[1:]:
        if num == current_end + 1:
            current_end = num
        else:
            if current_start == current_end:
                ranges.append(str(current_start))
            else:
                ranges.append(f"{current_start}-{current_end}")
            current_start = num
            current_end = num
    # Add the last range
    if current_start == current_end:
        ranges.append(str(current_start))
    else:
        ranges.append(f"{current_start}-{current_end}")
    return ','.join(ranges)

